[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$ProjectPath)
$ErrorActionPreference='Stop';$ProjectPath=[IO.Path]::GetFullPath($ProjectPath)
$root=Join-Path $ProjectPath 'Research\Verification\Gate10R_Attempt4_Preflight\v2';$officialRoot=Join-Path $ProjectPath 'Research\Verification\Gate10R_ProcessReuse_5pct\v4'
if(Test-Path -LiteralPath $officialRoot){throw 'Official v4 root exists.'};if(@(Get-Process Unity -ErrorAction SilentlyContinue).Count -ne 0){throw 'Unity is running.'}
function Get-LowerSha([string]$Path){(Get-FileHash -Algorithm SHA256 -LiteralPath $Path).Hash.ToLowerInvariant()}
function Write-AtomicJson([string]$Path,$Value){if(Test-Path -LiteralPath $Path){throw "Refusing overwrite: $Path"};$json=($Value|ConvertTo-Json -Depth 50).Replace("`r`n","`n").Replace("`r","`n");if(-not$json.EndsWith("`n",[StringComparison]::Ordinal)){$json+="`n"};$tmp=$Path+'.tmp-'+[guid]::NewGuid().ToString('N');$encoding=New-Object Text.UTF8Encoding($false,$true);[IO.File]::WriteAllText($tmp,$json,$encoding);[IO.File]::Move($tmp,$Path)}
$summaryPath=Join-Path $root 'Gate10R_Attempt4_OutsideRoot_Preflight.summary.v4.json';if((Get-LowerSha $summaryPath) -ne 'c1876860cc446a4def49ba3acac4193f305e1482f92db60c99b2280c61fa2e4c'){throw 'Failed v2 summary changed.'}
$summary=Get-Content -LiteralPath $summaryPath -Raw -Encoding UTF8|ConvertFrom-Json;$failed=@($summary.checks|Where-Object{-not$_.passed});if($summary.passed -ne $false -or $failed.Count -ne 1 -or [string]$failed[0].name -ne 'output-isolation-reject-original-summary'){throw 'Unexpected v2 failure shape.'}
$existing=@(Get-ChildItem -LiteralPath $root -Recurse -File -Force|Sort-Object FullName);$artifacts=@($existing|ForEach-Object{[ordered]@{relativePath=$_.FullName.Substring($root.Length).TrimStart('\').Replace('\','/');bytes=[long]$_.Length;sha256=Get-LowerSha $_.FullName}})
$manifestPath=Join-Path $root 'Gate10R_Attempt4_OutsideRoot_Preflight_Partial_Manifest.v2.json';$receiptPath=Join-Path $root 'Gate10R_Attempt4_OutsideRoot_Preflight_Failure_Receipt.v2.json';$checkpointPath=Join-Path $root 'gate10r-attempt4-outside-root-preflight-checkpoint.v2.json'
$manifest=[ordered]@{schemaVersion=1;manifestId='gate10r-attempt4-outside-root-preflight-v2-partial';createdAtUtc=[DateTime]::UtcNow.ToString('o');status='FAILED-PREDICATE-EXPECTED-EXISTING-ORIGINAL-SUMMARY';artifactCount=$artifacts.Count;rawBytes=[long](($existing|Measure-Object Length -Sum).Sum);artifacts=$artifacts;officialV4RootCreated=$false;unityStarted=$false};Write-AtomicJson $manifestPath $manifest
$receipt=[ordered]@{schemaVersion=1;receiptId='gate10r-attempt4-outside-root-preflight-v2-failure';createdAtUtc=[DateTime]::UtcNow.ToString('o');status='FAILED-ATOMICALLY-CLOSED-RETRY-AUTHORIZED';attempt=4;preflightExecutionOrdinal=2;failureClass='NEGATIVE-PREDICATE-REQUIRED-PREEXISTING-ORIGINAL-TO-BE-ABSENT';failedCheck='output-isolation-reject-original-summary';validatedFacts=[ordered]@{childExitCode=1;originalSummarySha256='1536ae459c3d8cbb90b8a9dad1f74e7937d5ceb205e6cc088745c798d136e54d';retainedSmokePassed=$true;retainedSmokeAssertionCount=63};repairBoundary='For the pre-existing original summary negative, require nonzero child exit and unchanged frozen SHA-256; retain absence predicate only for a new forbidden target.';partialManifestSha256=Get-LowerSha $manifestPath;officialV4RootCreated=$false;unityStarted=$false;automaticRetryAuthorized=$true;resumeThisRootAllowed=$false;nextPreflightRoot='Research/Verification/Gate10R_Attempt4_Preflight/v3';gate11RAuthorized=$false;gate12RAuthorized=$false;gate13RAuthorized=$false};Write-AtomicJson $receiptPath $receipt
$checkpoint=[ordered]@{schemaVersion=1;checkpointKind='gate10r-attempt4-outside-root-preflight-v2';savedAtUtc=[DateTime]::UtcNow.ToString('o');status='GATE10R-ATTEMPT4-OUTSIDE-PREFLIGHT-V2-FAILED-CLOSED-RETRY-V3-AUTHORIZED';failureReceiptSha256=Get-LowerSha $receiptPath;partialManifestSha256=Get-LowerSha $manifestPath;officialExecutionCount=0;officialV4RootCreated=$false;unityStarted=$false;resumeAllowed=$false;gate11RAuthorized=$false;gate12RAuthorized=$false;gate13RAuthorized=$false};Write-AtomicJson $checkpointPath $checkpoint
$checkpoint|ConvertTo-Json -Depth 10
